import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'

const output = process.argv[2]
const { GITHUB_SERVER_URL, GITHUB_REPOSITORY, GITHUB_RUN_ID } = process.env

execFileSync('pnpm', ['exec', 'changelogithub', '--to', 'HEAD', '--output', output], {
  stdio: 'inherit',
})

// link usernames instead of mentioning them, so contributors are not notified twice
const changelog = readFileSync(output, 'utf-8').replace(
  /\B@([a-z0-9](?:[a-z0-9-]*[a-z0-9])?)(?![\w-]|[./]\w)/gi,
  '[$1](https://github.com/$1)',
)

writeFileSync(
  output,
  [
    `Release PR generated by the Prepare Publish workflow: ${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}`,
    '',
    '## Changelog',
    '',
    changelog,
  ].join('\n'),
)
